with metrics as (select id, device_code, reading_ts, temp_c, pressure, avg(temp_c) over w_recent last4_avg_temp_c, min(temp_c) over w_recent last4_min_temp_c, count(temp_c) over w_recent last4_count_temp_c from device_readings where pressure is null window w_recent as (partition by device_code order by status_bits, id rows between 3 preceding and current row)) select id, device_code, reading_ts, temp_c, pressure, case when device_code rlike '^(DV-04|DV-03)$' then 'GROUP_B' else 'OTHER_ZONE' end as device_code_zone from metrics order by pressure desc nulls first, device_code_zone
